namespace MASS4.Graph.Generator;

static class AttributeDefinitions
{
    public const string Source = """
// <auto-generated/>
#nullable enable
using System;
namespace MASS4.Graph;

/// <summary>Names the generated assembly module and its prerequisite providers.</summary>
/// <param name="name">Fully qualified module name.</param>
/// <param name="prerequisites">Types with static Register(GraphTypeRegistry) methods.</param>
[AttributeUsage(AttributeTargets.Assembly)]
internal sealed class GraphModuleAttribute(string name, params Type[] prerequisites) : Attribute
{
    /// <summary>Fully qualified module name.</summary>
    public string Name { get; } = name;
    /// <summary>Prerequisite registration providers.</summary>
    public Type[] Prerequisites { get; } = prerequisites;
}

/// <summary>Declares a node on a top-level static partial class.</summary>
/// <param name="id">Explicit nonempty GUID, independent of source names.</param>
/// <param name="name">Display name.</param>
[AttributeUsage(AttributeTargets.Class)]
internal sealed class GraphNodeAttribute(string id, string name) : Attribute
{
    /// <summary>Persistent identity.</summary>
    public string Id { get; } = id;
    /// <summary>Display name.</summary>
    public string Name { get; } = name;
    /// <summary>Current payload version.</summary>
    public int Version { get; set; } = 1;
    /// <summary>Whether the node converts one input to one output.</summary>
    public bool Conversion { get; set; }
    /// <summary>Boolean type identity for a State guarded-transition helper, including its migration.</summary>
    public string? GuardType { get; set; }
    /// <summary>Boolean GraphValue declaration for a State guarded-transition helper; typed alternative to GuardType.</summary>
    public Type? Guard { get; set; }
}

/// <summary>Declares an ordered port, public key and domain storage type.</summary>
/// <param name="member">Generated member name.</param>
/// <param name="key">Persistent key scoped to the node.</param>
/// <param name="name">Display name.</param>
/// <param name="direction">Connection direction.</param>
/// <param name="typeId">Persistent carried type.</param>
/// <param name="valueType">CLR type or flow marker.</param>
[AttributeUsage(AttributeTargets.Class, AllowMultiple = true)]
internal sealed class GraphPortAttribute(
    string member, string key, string name, PortDirection direction, string typeId, Type valueType) : Attribute
{
    /// <summary>Declares a port carrying a GraphValue declared in source; its identity and CLR type follow that declaration.</summary>
    /// <param name="member">Generated member name.</param>
    /// <param name="key">Persistent key scoped to the node.</param>
    /// <param name="name">Display name.</param>
    /// <param name="direction">Connection direction.</param>
    /// <param name="value">GraphValue declaration.</param>
    public GraphPortAttribute(string member, string key, string name, PortDirection direction, Type value)
        : this(member, key, name, direction, "", value)
    {
    }

    /// <summary>Generated member name.</summary>
    public string Member { get; } = member;
    /// <summary>Persistent port key.</summary>
    public string Key { get; } = key;
    /// <summary>Display name.</summary>
    public string Name { get; } = name;
    /// <summary>Connection direction.</summary>
    public PortDirection Direction { get; } = direction;
    /// <summary>Carried type identity; empty when declared through a GraphValue declaration.</summary>
    public string PortTypeId { get; } = typeId;
    /// <summary>CLR type, flow marker or GraphValue declaration.</summary>
    public Type ValueType { get; } = valueType;
    /// <summary>Connection limit; defaults to single for inputs and multiple for outputs.</summary>
    public PortMultiplicity Multiplicity { get; set; } = (PortMultiplicity)(-1);
}

/// <summary>Declares a port type and its semantics storage together.</summary>
/// <param name="id">Persistent identity.</param>
/// <param name="name">Display name.</param>
/// <param name="valueType">Unmanaged or reference CLR type.</param>
[AttributeUsage(AttributeTargets.Class)]
internal sealed class GraphValueAttribute(string id, string name, Type valueType) : Attribute
{
    /// <summary>Persistent identity.</summary>
    public string Id { get; } = id;
    /// <summary>Display name.</summary>
    public string Name { get; } = name;
    /// <summary>CLR storage type.</summary>
    public Type ValueType { get; } = valueType;
    /// <summary>Optional serializer for a domain wire format.</summary>
    public Type? Serializer { get; set; }
    /// <summary>Optional user-declared source-generated JSON context.</summary>
    public Type? JsonContext { get; set; }
}

/// <summary>Declares a signal on a top-level static partial class.</summary>
/// <param name="id">Persistent identity.</param>
/// <param name="name">Display name.</param>
[AttributeUsage(AttributeTargets.Class)]
internal sealed class GraphSignalAttribute(string id, string name) : Attribute
{
    /// <summary>Persistent identity.</summary>
    public string Id { get; } = id;
    /// <summary>Display name.</summary>
    public string Name { get; } = name;
}

/// <summary>Records an obsolete identity next to its replacement.</summary>
/// <param name="id">Obsolete identity, which cannot also be registered.</param>
[AttributeUsage(AttributeTargets.Class, AllowMultiple = true)]
internal sealed class GraphRenamedFromAttribute(string id) : Attribute
{
    /// <summary>Obsolete persistent identity.</summary>
    public string Id { get; } = id;
}

/// <summary>Semantics binding emitted for a node.</summary>
internal enum GraphBehaviorKind
{
    /// <summary>A static method accepting DataflowContext.</summary>
    Dataflow,
    /// <summary>An IControlNode implementation.</summary>
    Control,
    /// <summary>An IStateNode implementation.</summary>
    State,
    /// <summary>An ITransitionNode implementation.</summary>
    Transition,
}

/// <summary>Declares a semantics binding without runtime discovery.</summary>
/// <param name="kind">Binding kind.</param>
/// <param name="type">Evaluation method owner or behavior implementation.</param>
[AttributeUsage(AttributeTargets.Class)]
internal sealed class GraphBehaviorAttribute(GraphBehaviorKind kind, Type type) : Attribute
{
    /// <summary>Binding kind.</summary>
    public GraphBehaviorKind Kind { get; } = kind;
    /// <summary>Evaluation owner or behavior implementation.</summary>
    public Type Type { get; } = type;
    /// <summary>Static dataflow evaluation method.</summary>
    public string? Method { get; set; }
    /// <summary>Whether dataflow results depend on changing host context.</summary>
    public bool Volatile { get; set; }
    /// <summary>Context features required by the dataflow behavior.</summary>
    public Type[] Features { get; set; } = [];
}

/// <summary>Declares payload serialization and an optional default factory on a node.</summary>
/// <param name="type">Payload CLR type.</param>
[AttributeUsage(AttributeTargets.Class)]
internal sealed class GraphPayloadAttribute(Type type) : Attribute
{
    /// <summary>Payload CLR type.</summary>
    public Type Type { get; } = type;
    /// <summary>User-declared source-generated JSON context for object payloads.</summary>
    public Type? JsonContext { get; set; }
    /// <summary>Generated value declaration reused by a single-value payload.</summary>
    public Type? Value { get; set; }
    /// <summary>Single-value property passed to its one-argument constructor.</summary>
    public string Member { get; set; } = "Value";
    /// <summary>Static parameterless default factory on this node declaration.</summary>
    public string? DefaultFactory { get; set; }
}

/// <summary>
/// Compiles a saved graph asset into this partial class: an ICompiledGraph specialised to the asset's topology,
/// with direct behavior calls and the interpreter's instance layout. Add the asset as an AdditionalFiles item.
/// </summary>
/// <param name="path">Path of the asset, matched against the end of an AdditionalFiles path.</param>
[AttributeUsage(AttributeTargets.Class)]
internal sealed class GraphAssetAttribute(string path) : Attribute
{
    /// <summary>Path of the asset.</summary>
    public string Path { get; } = path;
}

/// <summary>Declares a JsonObject-to-JsonObject migration method on a node.</summary>
/// <param name="fromVersion">Version upgraded by this step.</param>
/// <param name="owner">Static method owner.</param>
/// <param name="method">Static method name.</param>
[AttributeUsage(AttributeTargets.Class, AllowMultiple = true)]
internal sealed class GraphMigrationAttribute(int fromVersion, Type owner, string method) : Attribute
{
    /// <summary>Input version.</summary>
    public int FromVersion { get; } = fromVersion;
    /// <summary>Static method owner.</summary>
    public Type Owner { get; } = owner;
    /// <summary>Static method name.</summary>
    public string Method { get; } = method;
}

""";
}
